//! Real direct GSUB Type 5 references independently extracted from original SFNT bytes.
use rwcore::*;
type Rule=(&'static [u16],&'static [(u16,u16)]);
type Set=Option<&'static [Rule]>;
fn actions(a:&[(u16,u16)])->Vec<ContextAction>{a.iter().map(|&(sequence_index,lookup_index)|ContextAction{sequence_index,lookup_index}).collect()}
fn verify_rules(actual:Option<&[ContextRule]>,expected:Set){
    match (actual,expected){
        (None,None)=>{},
        (Some(a),Some(e))=>{assert_eq!(a.len(),e.len());for (r,&(tail,refs)) in a.iter().zip(e){assert_eq!(r.remaining,tail);assert_eq!(r.actions,actions(refs));}},
        _=>panic!("rule-set mismatch"),
    }
}
fn verify_match(actual:Option<ContextMatch<'_>>,expected:Option<&Rule>){
    match (actual,expected){
        (None,None)=>{},
        (Some(m),Some(&(tail,refs)))=>{assert_eq!(m.input_len,tail.len()+1);assert_eq!(m.actions,actions(refs));},
        _=>panic!("context match mismatch"),
    }
}
fn check_glyph(b:&[u8],glyphs:u32,lookups:usize,ids:&[u16],sets:&[Set]){
    let r=parse_context_substitution(b,glyphs,lookups,ContextLimits::default()).unwrap();
    assert_eq!(r.len(),ids.len());
    for id in 0..glyphs as u16{
        let e=ids.binary_search(&id).ok().and_then(|i|sets[i]);
        verify_rules(r.rules(id),e);
        if let Some(rs)=e{for &(tail,_) in rs{
            let mut input=vec![id];input.extend_from_slice(tail);
            for n in 1..=input.len(){
                let p=&input[..n];
                verify_match(r.match_prefix(p),rs.iter().find(|rule|p[1..].starts_with(rule.0)));
            }
        }}else{assert!(r.match_prefix(&[id]).is_none());}
    }
}
fn check_class(b:&[u8],glyphs:u32,lookups:usize,ids:&[u16],classes:&[(u16,u16,u16)],sets:&[Set]){
    let r=parse_class_context_substitution(b,glyphs,lookups,ContextLimits::default()).unwrap();
    let class=|id:u16|classes.iter().find(|&&(a,z,_)|a<=id&&id<=z).map_or(0,|x|x.2);
    for id in 0..glyphs as u16{
        let e=if ids.binary_search(&id).is_ok(){sets[usize::from(class(id))]}else{None};
        verify_rules(r.rules(id),e);
        if let Some(rs)=e{for &(tail,_) in rs{
            let mut input=vec![id];
            for &c in tail{input.push((0..glyphs as u16).find(|&g|class(g)==c).unwrap());}
            for n in 1..=input.len(){
                let p=&input[..n];
                verify_match(r.match_prefix(p),rs.iter().find(|rule|p.len()>rule.0.len()&&rule.0.iter().zip(&p[1..]).all(|(&c,&g)|class(g)==c)));
            }
        }}else{assert!(r.match_prefix(&[id]).is_none());}
    }
}
fn check_cov(b:&[u8],glyphs:u32,lookups:usize,covs:&[&[u16]],refs:&[(u16,u16)]){
    let r=parse_coverage_context_substitution(b,glyphs,lookups,ContextLimits::default()).unwrap();
    assert_eq!(r.input_len(),covs.len());assert_eq!(r.actions(),actions(refs));
    let mut input:Vec<u16>=covs.iter().map(|c|c[0]).collect();
    for (i,c) in covs.iter().enumerate(){
        assert_eq!(r.coverages()[i].len() as usize,c.len());
        let old=input[i];
        for id in 0..glyphs as u16{
            let expected=c.binary_search(&id).is_ok();
            assert_eq!(r.coverages()[i].index(id).is_some(),expected);
            input[i]=id;
            assert_eq!(r.match_prefix(&input).is_some(),expected);
        }
        input[i]=old;
    }
    let m=r.match_prefix(&input).unwrap();assert_eq!(m.input_len,covs.len());assert_eq!(m.actions,actions(refs));
    assert!(r.match_prefix(&input[..input.len()-1]).is_none());
}
