    let c=parse_font(include_bytes!("fixtures/notosansdevanagari/NotoSansDevanagari[wdth,wght].ttf"),FontLimits::default()).unwrap();
    let b=c.face(0).unwrap().table(*b"GSUB").unwrap();
    let g=parse_gsub_layout(b,GsubLimits::default()).unwrap();
